#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // In-place Doolittle LU factorization without pivoting:
    // A(i,j) for i<=j stores U, and A(i,j) for i>j stores L (with implicit L diagonal = 1).
    for (size_t k = 0; k < N; ++k) {
        const size_t kk = k * N + k;
        const double pivot = A[kk];

        // If pivot is zero, factorization without pivoting is not possible.
        // Leave matrix as-is from this point.
        if (pivot == 0.0) {
            return;
        }

        // Compute L(i,k) = A(i,k) / U(k,k) for i = k+1..N-1
        #pragma omp parallel for default(none) shared(A, N, k, pivot)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k + 1); i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Trailing submatrix update:
        // A(i,j) -= L(i,k) * U(k,j), for i,j = k+1..N-1
        #pragma omp parallel for collapse(2) default(none) shared(A, N, k)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k + 1); i < static_cast<std::ptrdiff_t>(N); ++i) {
            for (std::ptrdiff_t j = static_cast<std::ptrdiff_t>(k + 1); j < static_cast<std::ptrdiff_t>(N); ++j) {
                const size_t iu = static_cast<size_t>(i);
                const size_t ju = static_cast<size_t>(j);
                A[iu * N + ju] -= A[iu * N + k] * A[k * N + ju];
            }
        }
    }
}
